/// <summary>
/// submitBinCounts' request. RowsJson: LineNumber, BinId, Quantity.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountBinLinesRequest
{
    DataAreaId dataAreaId;
    InventJournalId journalId;
    str userId;
    str submissionId;
    str rowsJson;
}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('JournalId')]
public InventJournalId parmJournalId(InventJournalId _value = journalId)
{
    journalId = _value;
    return journalId;
}

[DataMemberAttribute('UserId')]
public str parmUserId(str _value = userId)
{
    userId = _value;
    return userId;
}

[DataMemberAttribute('SubmissionId')]
public str parmSubmissionId(str _value = submissionId)
{
    submissionId = _value;
    return submissionId;
}

[DataMemberAttribute('RowsJson')]
public str parmRowsJson(str _value = rowsJson)
{
    rowsJson = _value;
    return rowsJson;
}
